import{_ as t,o as s,c as o,ah as n,j as e}from"./chunks/framework.j6VUGC9R.js";const i="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image2.DwGsU4w_.png",r="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image3.CEwFiF1p.png",p="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image3.DL61rBrU.png",l="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image5.BqA9nktn.png",c="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image6.BX6fJUSy.png",d="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image7.DiNRj6Fy.png",A="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image8.CGvearBG.png",h="data:image/png;base64,",u="data:image/png;base64,",m="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image11.ojbPgfVD.png",g="/projects/Black-Mecanum-Wheel-Chassis/en/latest/assets/image19.DCx0Vnsv.png",D=JSON.parse('{"title":"3. Development Tutorial (Arduino)","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3._Arduino_checked.md","filePath":"docs/3._Arduino_checked.md"}'),_={name:"docs/3._Arduino_checked.md"};function f(v,a,w,b,y,T){return s(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="_3-development-tutorial-arduino" tabindex="-1">3. Development Tutorial (Arduino) <a class="header-anchor" href="#_3-development-tutorial-arduino" aria-label="Permalink to &quot;3. Development Tutorial (Arduino)&quot;">​</a></h1><p>After the program is successfully downloaded, the robot chassis will execute the movements in the following predefined sequence:</p><p>(1) Move Forward</p><p>(2) Move Backward</p><p>(3) Move Left or Right (Lateral Movement)</p><p>(4) Turn Left or Right in Place</p><p>(5) Move Left-Forward and Right-Backward (Diagonal Movement)</p><p>(6) Drift Left or Right in Place</p><p>Each action will be executed for <strong>2 seconds</strong>.</p><p>There will be a <strong>1-second interval</strong> between the execution of different actions.</p><h2 id="_3-1-arduino-installation-wiring" tabindex="-1">3.1 Arduino Installation &amp; Wiring <a class="header-anchor" href="#_3-1-arduino-installation-wiring" aria-label="Permalink to &quot;3.1 Arduino Installation &amp; Wiring&quot;">​</a></h2><p>(1) Hardware Required for Arduino Development</p>',12),e("p",null,[e("iframe",{width:"100%",height:"713",src:"https://www.youtube.com/embed/630vloYGBCw",title:"Black Mecanum-Wheel Chassis Tutorials--01 Hardware Required for Arduino Development (Arduino)",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1),e("p",null,"(2) Motor Driver Installation",-1),e("p",null,[e("iframe",{width:"100%",height:"713",src:"https://www.youtube.com/embed/HUKgHG93AQo",title:"Black Mecanum-Wheel Chassis Tutorials--02 Motor Driver Installation (Arduino)",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1),e("p",null,"(3) Arduino Installation",-1),e("p",null,[e("iframe",{width:"100%",height:"713",src:"https://www.youtube.com/embed/IpOa0ItUcDs",title:"Black Mecanum-Wheel Chassis Tutorials--03 Arduino Installation",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1),e("p",null,"(4) Wring",-1),e("p",null,[e("iframe",{width:"100%",height:"713",src:"https://www.youtube.com/embed/sWf5xdIucMU",title:"Black Mecanum-Wheel Chassis Tutorials--04 Wring (Arduino)",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1),e("p",null,"(5) Battery Installation & Wiring",-1),e("p",null,[e("iframe",{width:"100%",height:"713",src:"https://www.youtube.com/embed/NYJ3hhh6RAk",title:"Black Mecanum-Wheel Chassis Tutorials--05 Battery Installation & Wiring (Arduino)",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1),n('<h2 id="_3-2-hardware-introduction" tabindex="-1">3.2 Hardware Introduction <a class="header-anchor" href="#_3-2-hardware-introduction" aria-label="Permalink to &quot;3.2 Hardware Introduction&quot;">​</a></h2><h3 id="_3-2-1-arduino-uno" tabindex="-1">3.2.1 Arduino Uno <a class="header-anchor" href="#_3-2-1-arduino-uno" aria-label="Permalink to &quot;3.2.1 Arduino Uno&quot;">​</a></h3><p>The <code>Arduino Uno</code> is a versatile and beginner-friendly open-source electronics prototyping platform. It features 14 digital input/output pins (6 of which can be used as <code>PWM</code> outputs), 6 analog input pins, a 16 MHz ceramic resonator (<code>CSTCE16M0V53-R0</code>), a USB connection, a power jack, an <code>ICSP</code> header, and a reset button.</p><p>Below is a schematic diagram of the <code>Arduino Uno</code> physical pins (please refer to your specific <code>Arduino Uno</code> board for accurate pinout details):</p><img loading="lazy" height="774" width="1027" src="'+i+'" class="common_img"><h3 id="_3-2-2-4-channel-motor-driver" tabindex="-1">3.2.2 4-Channel Motor Driver <a class="header-anchor" href="#_3-2-2-4-channel-motor-driver" aria-label="Permalink to &quot;3.2.2 4-Channel Motor Driver&quot;">​</a></h3><p>This motor driver module is designed to work with a microcontroller to drive TT motors or magnetic encoder motors. Each channel is equipped with a motor driver chip (<code>YX-4055AM</code>), with an operating voltage range of DC 3V-12V. The specific voltage should match the motor being connected. The pin layout is shown in the diagram below:</p><img loading="lazy" height="676" width="696" src="'+r+'" class="common_img"><ul><li><strong>Interface Pin Description</strong></li></ul><table class="docutils-nobg" border="1"><tr><th rowspan="7">Encoder Motor Interface</th><td>GND</td><td>Hall power negative</td></tr><tr><td>A</td><td>Phase A pulse signal output</td></tr><tr><td>B</td><td>Phase B pulse signal output</td></tr><tr><td>VCC</td><td>Hall power positive</td></tr><tr><td>M+</td><td>Motor power positive</td></tr><tr><td>M-</td><td>Motor power negative</td></tr><tr><td colspan="2">Note:The voltage between `VCC` and `GND` is determined by the power supply voltage of the microcontroller, typically 3.3V or 5V.<br>When the motor shaft rotates clockwise, the A channel pulse signal precedes the B channel signal. When the shaft rotates counterclockwise, the A channel signal follows the B channel.<br><br>The voltage between `M+` and `M-` depends on the motor voltage.</td></tr><tr><th rowspan="4">IIC</th><td>SCL</td><td>Clock line</td></tr><tr><td>SDA</td><td>Bidirectional data line</td></tr><tr><td>GND</td><td>Ground</td></tr><tr><td>5V</td><td>5V DC output</td></tr><tr><th rowspan="3">3Pin power interface</th><td>-</td><td>Power negative input</td></tr><tr><td>+</td><td>Power positive input</td></tr><tr><td>NC</td><td>Not connected</td></tr><tr><th rowspan="2">Power interface</th><td>+</td><td>Power positive input</td></tr><tr><td>-</td><td>Power negative</td></tr></table><h3 id="_3-2-3-encoder-reduction-motor" tabindex="-1">3.2.3 Encoder Reduction Motor <a class="header-anchor" href="#_3-2-3-encoder-reduction-motor" aria-label="Permalink to &quot;3.2.3 Encoder Reduction Motor&quot;">​</a></h3><p>The chassis is equipped with a motor model <code>JGB37-528R131-08</code>. The designation details are as follows:</p><p>(1) J: DC motor</p><p>(2) GB: Offset output shaft</p><p>(3) 37: Gearbox diameter (mm)</p><p>(4) 528: Motor model number</p><p>(5) R131: Reduction ratio of 131:1</p><p>(6) 08: Rated voltage of 8V</p><p>The interface details are shown in the diagram below:</p><img loading="lazy" height="511" width="744" src="'+p+'" class="common_img"><h2 id="_3-3-wiring-instructions" tabindex="-1">3.3 Wiring Instructions <a class="header-anchor" href="#_3-3-wiring-instructions" aria-label="Permalink to &quot;3.3 Wiring Instructions&quot;">​</a></h2><p><code>Arduino Uno</code> with 4-Channel Encoder Motor Driver Module, powered by a 7.4V 2200mAh lithium battery to drive the motors. The following is the general wiring diagram for <code>Arduino Uno</code> control:</p><img loading="lazy" height="856" width="887" src="'+l+'" class="common_img"><img loading="lazy" height="562" width="898" src="'+c+'" class="common_img"><h2 id="_3-4-environment-configuration-and-program-download" tabindex="-1">3.4 Environment Configuration and Program Download <a class="header-anchor" href="#_3-4-environment-configuration-and-program-download" aria-label="Permalink to &quot;3.4 Environment Configuration and Program Download&quot;">​</a></h2><h3 id="_3-4-1-environment-configuration" tabindex="-1">3.4.1 Environment Configuration <a class="header-anchor" href="#_3-4-1-environment-configuration" aria-label="Permalink to &quot;3.4.1 Environment Configuration&quot;">​</a></h3><p>Prior to downloading, ensure that the Arduino IDE is installed on your computer. You can find the software package in the <a href="./Appendix.html">Appendix-&gt;Arduino Installation Package</a>.</p><h3 id="_3-4-2-program-running" tabindex="-1">3.4.2 Program Running <a class="header-anchor" href="#_3-4-2-program-running" aria-label="Permalink to &quot;3.4.2 Program Running&quot;">​</a></h3><p>Open the <strong>&quot;car_move_demo.ino&quot;</strong> program saved in <a href="./Appendix.html">Appendix-&gt;car_move_demo</a> using Arduino IDE.</p><p>(1) Choose the Arduino development board type. In this case, select <strong>&quot;Arduino UNO&quot;</strong></p><img loading="lazy" height="303" width="641" src="'+d+'" class="common_img"><p>(2) Select the USB port the Arduino currently connecting to your computer. The IDE will detect it automatically; in this case, choose <strong>&quot;COM61&quot;</strong>.</p><img loading="lazy" height="245" width="572" src="'+A+'" class="common_img"><p>(3) Connect <code>Arduino UNO</code> to the computer. Select <strong>&quot;Arduino UNO&quot;</strong> in the tool bar, and click-on <img loading="lazy" height="24" width="28" src="'+h+'"> to download the program.</p><p>(4) The software will compile the program automatically. Please wait until the compilation process is successfully completed.</p><img loading="lazy" height="188" width="631" src="'+u+'" class="common_img"><p>(5) Wait for the program to finish uploading.</p><img loading="lazy" height="188" width="1471" src="'+m+'" class="common_img"><h3 id="_3-4-3-program-outcome" tabindex="-1">3.4.3 Program Outcome <a class="header-anchor" href="#_3-4-3-program-outcome" aria-label="Permalink to &quot;3.4.3 Program Outcome&quot;">​</a></h3><p>After downloading the program, the robot chassis will execute actions in the following predetermined order:</p><p>(1) Move forward</p><p>(2) Move backward</p><p>(3) Move left</p><p>(4) Move right</p><p>(4) Turn left</p><p>(5) Move backward left</p><p>(6) Turn right</p><p>(7) Move backward right</p><p>(8) Rotate left in place</p><p>(9) Rotate right in place</p><p>Each action will run for 2 seconds, with a 1-second interval between each action.</p><h2 id="_3-5-sample-program-brief-analysis" tabindex="-1">3.5 Sample Program Brief Analysis <a class="header-anchor" href="#_3-5-sample-program-brief-analysis" aria-label="Permalink to &quot;3.5 Sample Program Brief Analysis&quot;">​</a></h2><p><a href="../_static/source_code/car_move_demo.zip">Source Code</a></p><ul><li><strong>Import Necessary Libraries</strong></li></ul><p>The required packages are built into the Arduino IDE. Go to <strong>&quot;Project -&gt; Load Libraries&quot;</strong> to add them. These libraries contain methods for <code>IIC</code> communication, which are used to control the rotation of motors.</p>',55),e("p",{"lineno-start":"1"},null,-1),n('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;Wire.h&gt;</span></span></code></pre></div><ul><li><strong>Initialize Communication Address</strong></li></ul><p>Define macros for the <code>IIC</code> communication address and the addresses of various motor types to make future calls easier. The default <code>IIC</code> communication address for the driver board is <code>0x34</code>, which can be left as default based on your hardware. Set the encoder motor type address <code>MOTOR_TYPE_ADDR</code> to <code>20</code>. These numbers represent the address locations for writing parameters, not the actual parameter values, which depend on your hardware. Keep the defaults for now. For motor control, the address <code>MOTOR_FIXED_SPEED_ADDR</code> is set to <code>51</code>, which is the address for speed control of the four encoder motors. If speed control for the chassis motors is needed in future, you can change this address during <code>IIC</code> interface writes, but for now, keep it as default.</p>',3),e("p",{"lineno-start":"3"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define I2C_ADDR        0x34</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define ADC_BAT_ADDR                  0</span></span>
<span class="line"><span>#define MOTOR_TYPE_ADDR               20</span><span> // Encoder motor type setting</span></span>
<span class="line"><span>#define MOTOR_ENCODER_POLARITY_ADDR   21</span><span> // Set encoder direction polarity</span></span>
<span class="line"><span>// If you find the motor speed is completely uncontrollable (either running at max speed or stopped),</span></span>
<span class="line"><span>// you may need to reconfigure the value at this address</span></span>
<span class="line"><span>// Range: 0 or 1, default is 0</span></span>
<span class="line"><span>#define MOTOR_FIXED_PWM_ADDR      31</span><span> // Fixed PWM control (open-loop control), range (-100~100)</span></span>
<span class="line"><span>//#define SERVOS_ADDR_CMD 40        </span></span>
<span class="line"><span>#define MOTOR_FIXED_SPEED_ADDR    51</span><span> // Fixed speed control (closed-loop control),</span></span>
<span class="line"><span>// Unit: pulses per 10ms. Range depends on specific encoder motor (affected by encoder line count,</span></span>
<span class="line"><span>// voltage, load, etc.), typically around ±50</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define MOTOR_ENCODER_TOTAL_ADDR  60</span><span> // Total pulse count for each of the 4 encoder motors</span></span>
<span class="line"><span>// If the pulses per revolution (U) is known and wheel diameter (D) is known,</span></span>
<span class="line"><span>// the travel distance can be calculated from pulse count:</span></span>
<span class="line"><span>// For example, if motor 1&#39;s total pulse count is P, then travel distance = (P/U) * (3.14159*D)</span></span>
<span class="line"><span>// For different motors, you can manually test U by rotating 10 turns and taking the average pulse count</span></span></code></pre></div><p>(2) Initialize Motor Type</p><p>The four-channel driver module supports various types of motors, including TTL, N20, and JGB motors. All motor types are defined as macros. In this development, we are using JGB motors, so the motor type macro is set to 3.</p>`,3),e("p",{"lineno-start":"21"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Motor type specific values  </span></span>
<span class="line"><span>#define MOTOR_TYPE_WITHOUT_ENCODER        0    </span></span>
<span class="line"><span>#define MOTOR_TYPE_TT                     1     </span></span>
<span class="line"><span>#define MOTOR_TYPE_N20                    2     </span></span>
<span class="line"><span>#define MOTOR_TYPE_JGB                    3</span><span>  // Magnetic encoder (44 pulses per revolution), gear ratio: 131 (default)</span></span></code></pre></div><ul><li><strong>Motor and Control Setup</strong></li></ul><p>The lines <code>MotorType = MOTOR_TYPE_JGB</code> and <code>MotorEncoderPolarity = 0</code> define the motor type and encoder polarity.</p><p>① <code>MOTOR_TYPE_JGB</code> is a predefined constant representing the JGB motor model.</p><p>② <code>MotorEncoderPolarity = 0</code> sets the encoder polarity to the default configuration.</p><p>③ <code>Wire.begin()</code> starts the <code>IIC</code> bus communication and initializes it with this function.</p><p>④ The functions <code>WireWriteDataArray(MOTOR_TYPE_ADDR, &amp;MotorType, 1)</code> and <code>WireWriteDataArray(MOTOR_ENCODER_POLARITY_ADDR, &amp;MotorEncoderPolarity, 1)</code> send the motor type and encoder polarity to the specified addresses via the <code>IIC</code> protocol.</p>`,7),e("p",{"lineno-start":"88"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint8_t MotorType = MOTOR_TYPE_JGB;</span></span>
<span class="line"><span>uint8_t MotorEncoderPolarity = 0; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>void setup()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  Wire.begin();</span></span>
<span class="line"><span>  delay(200);</span></span>
<span class="line"><span>  WireWriteDataArray(MOTOR_TYPE_ADDR,&amp;MotorType,1);</span></span>
<span class="line"><span>  delay(5);</span></span>
<span class="line"><span>  WireWriteDataArray(MOTOR_ENCODER_POLARITY_ADDR,&amp;MotorEncoderPolarity,1);</span></span>
<span class="line"><span>  delay(2000);</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><strong>Movement Action Setup</strong></li></ul><p>In the code, various motion types are set, including the initial motor speed for each action. For example, <code>car_forward[4] = {30, -30, -30, 30}</code> defines the motor speeds for M1, M2, M3, and M4. Since the motors may be mounted in reverse, the initial direction for forward motion must be configured. The speed range is recommended to be <code>[-50, 50]</code>.</p>`,3),e("p",{"lineno-start":"102"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int8_t car_forward[4] = {30, -30, -30, 30};       // Forward movement</span></span>
<span class="line"><span>int8_t car_back[4] = {-30, 30, 30, -30};          // Backward movement</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_left_transform[4] = {-30, -30, -30, -30};  // Left strafe (sideways)</span></span>
<span class="line"><span>int8_t car_right_transform[4] = {30, 30, 30, 30};     // Right strafe (sideways)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_turn_left[4] = {30, -30, -10, 10};      // Pivot turn left (forward arc)</span></span>
<span class="line"><span>int8_t car_turn_right[4] = {10, -10, -30, 30};     // Pivot turn right (forward arc)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_turn_left_back[4] = {-30, 30, 10, -10};  // Reverse pivot turn left</span></span>
<span class="line"><span>int8_t car_turn_right_back[4] = {-10, 10, 30, -30}; // Reverse pivot turn right</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_turn_right_orin[4] = {-30, 30, -30, 30}; // In-place clockwise rotation</span></span>
<span class="line"><span>int8_t car_turn_left_orin[4] = {30, -30, 30, -30};  // In-place counter-clockwise rotation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_Ob_translation_left_up[4] = {0, -30, -30, 0};  // Diagonal front-left movement</span></span>
<span class="line"><span>int8_t car_Ob_translation_right_up[4] = {30, 0, 0, 30};   // Diagonal front-right movement</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_Ob_translation_left_back[4] = {-30, 0, 0, -30}; // Diagonal rear-left movement</span></span>
<span class="line"><span>int8_t car_Ob_translation_right_back[4] = {0, 30, 30, 0};  // Diagonal rear-right movement</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_drift_left[4] = {-30, 0, -30, 0};      // Left drift </span></span>
<span class="line"><span>int8_t car_drift_right[4] = {30, 0, 30, 0};       // Right drift </span></span>
<span class="line"><span></span></span>
<span class="line"><span>int8_t car_stop[4] = {0, 0, 0, 0};                // Full stop</span></span></code></pre></div><ul><li><strong>Chassis Movement Execution Function</strong></li></ul><p>The <code>Running</code> function is used to execute the chassis movement. The <code>running_mode[4]</code> array stores the movement mode parameters, which correspond to previously defined actions. The <code>WireWriteDataArray(MOTOR_FIXED_SPEED_ADDR, running_mode, 4)</code> function writes the current motor speeds to control movement. After a delay of 2000 milliseconds (<code>delay(2000)</code>), the stop action <code>car_stop</code> is executed, with a duration of 1 second.</p>`,3),e("p",{"lineno-start":"130"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void Running(int8_t running_mode[4])</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  WireWriteDataArray(MOTOR_FIXED_SPEED_ADDR,running_mode,4);  //Perform the corresponding action.</span></span>
<span class="line"><span>  delay(2000);</span></span>
<span class="line"><span>  WireWriteDataArray(MOTOR_FIXED_SPEED_ADDR,car_stop,4);      // stop</span></span>
<span class="line"><span>  delay(1000);</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><strong>Main Function</strong></li></ul><p>In the main function, the previously written <code>Running</code> function is called with the corresponding action parameters, resulting in different motion effects. The functions execute in sequence, and by changing the parameters passed to the action functions, different movement sequences can be achieved.</p>`,3),e("p",{"lineno-start":"138"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void loop() </span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Execute various movement patterns sequentially</span></span>
<span class="line"><span>    Running(car_forward);                   // Move forward</span></span>
<span class="line"><span>    Running(car_back);                      // Move backward</span></span>
<span class="line"><span>    Running(car_left_transform);            // Strafe left </span></span>
<span class="line"><span>    Running(car_right_transform);           // Strafe right  </span></span>
<span class="line"><span>    Running(car_turn_left_orin);            // Rotate left in place</span></span>
<span class="line"><span>    Running(car_turn_right_orin);           // Rotate right in place</span></span>
<span class="line"><span>    Running(car_Ob_translation_left_up);    // Diagonal front-left movement</span></span>
<span class="line"><span>    Running(car_Ob_translation_right_back); // Diagonal rear-right movement</span></span>
<span class="line"><span>    Running(car_drift_left);                // Left drift maneuver</span></span>
<span class="line"><span>    Running(car_drift_right);               // Right drift maneuver</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    while(1){} // Infinite loop (halt execution after completing sequence)</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_3-6-development-notes" tabindex="-1">3.6 Development Notes <a class="header-anchor" href="#_3-6-development-notes" aria-label="Permalink to &quot;3.6 Development Notes&quot;">​</a></h2><p>(1) The rated working voltage for the <code>Arduino Uno</code> is 5V, with an input voltage range of 7-12V. However, the <code>IIC</code> interface of the four-motor encoder driver module cannot be used directly to power the <code>Arduino Uno</code>, as the 5V on <code>IIC</code> only supports voltage input and not output. Since the Mecanum wheels do not have additional sensors or components, the 5V output from the <code>IIC</code> serial interface of the four-motor encoder driver module can be used to power the <code>Arduino Uno</code>.</p><p>(2) When developing independently, it is recommended not to directly connect the positive and negative power terminals of the four-motor encoder driver module to the main controller&#39;s power supply terminals if no electrical protection circuit is available. This is to prevent damage to the main controller&#39;s resistors, capacitors, or the main controller chip. The position is shown in the red box in the diagram below: <img loading="lazy" height="547" width="433" src="`+g+'" class="common_img"></p>',4)])])}const R=t(_,[["render",f]]);export{D as __pageData,R as default};
